import * as THREE from "three";

// Pre-baked authoritative 128x128 RGBA textures for zero-overhead native mobile rendering
const B64_MAP: Record<string, string> = {
  chair: "",
  table: "",
  table_adjustable: "",
  gaming_chair: "",
  almirah: "",
  beanbag: "",
  screen: "",
  whiteboard: "",
  floor: "",
};


function base64ToUint8Array(b64: string): Uint8Array {
  if (typeof Buffer !== 'undefined') {
    return new Uint8Array(Buffer.from(b64, 'base64'));
  }
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

const textureCache: Map<string, THREE.DataTexture> = new Map();

export function getAuthoritativeDataTexture(name: string): THREE.DataTexture | null {
  if (textureCache.has(name)) {
    return textureCache.get(name)!;
  }
  const b64 = B64_MAP[name];
  if (!b64) return null;

  const data = base64ToUint8Array(b64);
  const tex = new THREE.DataTexture(data, 128, 128, THREE.RGBAFormat);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.wrapT = THREE.RepeatWrapping;
  if (name === 'floor') {
    tex.repeat.set(20, 20);
  }
  tex.minFilter = THREE.LinearMipmapLinearFilter;
  tex.magFilter = THREE.LinearFilter;
  tex.generateMipmaps = true;
  tex.needsUpdate = true;
  textureCache.set(name, tex);
  return tex;
}

export function bindAuthoritativeMaterials(scene: THREE.Object3D): void {
  const matToTexture: Record<string, string> = {
    'tripo_mat_3ce66be0': 'chair',
    'tripo_mat_4cb0bd4b': 'gaming_chair',
    'Material.001': 'table',
    'tripo_mat_83625889': 'table_adjustable',
    'tripo_mat_3a807052': 'almirah',
    'tripo_mat_0eb0c7ea': 'beanbag',
    'tripo_mat_d417ecab': 'screen',
    'tripo_mat_4648c5fa': 'whiteboard',
    'Carpet': 'floor',
  };

  const toRemove: THREE.Object3D[] = [];

  scene.traverse((child) => {
    // 1. Remove floating black cube artifacts (e.g. Cube.001 in air)
    if (
      child.name === 'Cube.001' ||
      (child.name.startsWith('Cube') && child.position.y > 1.5)
    ) {
      toRemove.push(child);
      return;
    }

    if ((child as THREE.Mesh).isMesh) {
      const mesh = child as THREE.Mesh;
      mesh.castShadow = true;
      mesh.receiveShadow = true;

      const materials = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
      for (const mat of materials) {
        if (!mat) continue;

        const stdMat = mat as THREE.MeshStandardMaterial;
        const matName = stdMat.name || '';
        const texKey = matToTexture[matName];

        if (texKey) {
          const tex = getAuthoritativeDataTexture(texKey);
          if (tex) {
            stdMat.map = tex;
            stdMat.color.setRGB(1.0, 1.0, 1.0);
            stdMat.roughness = 0.55;
            stdMat.metalness = 0.05;
            stdMat.needsUpdate = true;
          }
        } else if (matName === 'Material.003') {
          // Glass wall / window partition
          stdMat.color.setRGB(0.70, 0.85, 0.98);
          stdMat.transparent = true;
          stdMat.opacity = 0.35;
          stdMat.roughness = 0.10;
          stdMat.metalness = 0.10;
          stdMat.needsUpdate = true;
        } else if (matName === 'OffWhite' || matName === 'White' || !stdMat.map) {
          // Architectural wall / pillar surfaces: ensure clean, elegant look
          if (child.name.includes('Pillar') || child.name.includes('Wall') || child.name.includes('Side_Room')) {
            stdMat.color.setRGB(0.92, 0.93, 0.95);
            stdMat.roughness = 0.85;
            stdMat.metalness = 0.05;
            stdMat.needsUpdate = true;
          } else if (child.name.startsWith('Cube')) {
            // Floor obstacle cubes
            stdMat.color.setRGB(0.85, 0.40, 0.18);
            stdMat.roughness = 0.45;
            stdMat.metalness = 0.20;
            stdMat.needsUpdate = true;
          }
        }
      }
    }
  });

  for (const obj of toRemove) {
    obj.visible = false;
    if (obj.parent) {
      obj.parent.remove(obj);
    }
  }
}
